INSERT OR REPLACE INTO findings (doc, title, date, verdict, superseded_by, summary) VALUES (112, 'Liquidation cascades (OI proxy) and session behaviour', '2026-10-22', 'no signal from the proxy', NULL, 'BTC 15-min Sep 2025-Oct 2026: 385 cascade bars (OI drop in the 2% tail, range >= 2 ATR) vs 1,424 wide bars without an OI drop. Continuation 1h/4h/24h ~0 for both; extreme retested within 24h 77-80% both; continued >=1 ATR beyond 81-85% both. Asia long-cascade -> NY takes Asia low first 59% vs 46% base (n 32). OI build +3.5%/24h with flat price: next-24h range 3.58% vs 3.35%, direction t -0.25 and sign flips by half. A cascade is a wide bar; nothing more. Real liquidation LEVELS (ahead of price) remain untested - doc 110 steps 2-3.');
